CAT = "cpatcpCcorp"; SEG = "CCO"
Q = [
("A C corporation has gross income of $400,000, including $50,000 of dividends from a domestic corporation it owns 10% of, and $500,000 of deductible expenses. Its net operating loss for the year is:",
 "$125,000", ["$100,000", "$132,500", "$150,000"],
 "In a loss year the 50% dividends received deduction is not limited by taxable income (section 246(b)(2)): $400,000 - $500,000 - $25,000 = a $125,000 NOL.", 125000),
("A C corporation with a net operating loss for the year makes $8,000 of charitable contributions. The contributions:",
 "Carry forward 5 years", ["Increase the NOL", "Are deducted in full", "Carry back 2 years"],
 "With no taxable income there is no room under the corporate limit, so the gifts carry forward for 5 years (section 170(d)(2)). They are not part of the NOL."),
("A calendar-year corporation has a $140,000 NOL carryforward that arose in 2016 and no other NOLs. Its 2026 taxable income before the NOL deduction is $100,000. Its 2026 NOL deduction is:",
 "$100,000", ["$80,000", "$140,000", "$112,000"],
 "The 80% of taxable income limit applies only to losses arising in tax years beginning after 2017. A 2016 loss can offset all $100,000, and $40,000 carries on within its 20-year life.", 100000),
("After an ownership change, a loss corporation worth $5,000,000 just before the change may use pre-change NOLs each year up to the section 382 limit. Assuming a long-term tax-exempt rate of 3.4%, that limit is:",
 "$170,000", ["$1,050,000", "$136,000", "$210,000"],
 "The section 382 limit is the old loss corporation's value times the long-term tax-exempt rate: $5,000,000 x 3.4% = $170,000.", 170000),
("For section 382, an ownership change occurs when the stock owned by 5% shareholders rises by more than:",
 "50 points within 3 years", ["50 points within 1 year", "20 points within 3 years", "80 points within 5 years"],
 "An owner shift or equity structure shift that increases 5% shareholders' ownership by more than 50 percentage points over the 3-year testing period is an ownership change."),
("A calendar-year C corporation has a $30,000 net capital loss in 2026. It had net capital gains of $8,000 in 2023, $5,000 in 2024 and $10,000 in 2025. The capital loss carried forward to 2027 is:",
 "$7,000", ["$30,000", "$22,000", "$0"],
 "A corporate net capital loss is carried back 3 years, earliest first, then forward: $30,000 - $8,000 - $5,000 - $10,000 = $7,000, carried forward as short-term capital loss.", 7000),
("Ali transfers land with a basis of $40,000 and a value of $100,000 to a new corporation for stock worth $85,000 and $15,000 of cash, and owns 90% of it afterwards. His recognized gain is:",
 "$15,000", ["$60,000", "$0", "$45,000"],
 "Section 351 applies because he controls the corporation, so gain is recognized only up to the boot: the lesser of the $60,000 realized gain and the $15,000 cash.", 15000),
("Ali transfers land with a basis of $40,000 and a value of $100,000 to a new corporation for stock worth $85,000 and $15,000 of cash, recognizes $15,000 of gain and owns 90% of it afterwards. The corporation's basis in the land is:",
 "$55,000", ["$100,000", "$40,000", "$85,000"],
 "Under section 362(a) the corporation takes the transferor's basis plus gain he recognized: $40,000 + $15,000 = $55,000.", 55000),
("Bea transfers a building with a basis of $70,000 and a value of $200,000, subject to a $90,000 mortgage the corporation assumes, for all of its stock. She recognizes gain of:",
 "$20,000", ["$0", "$90,000", "$130,000"],
 "Under section 357(c), liabilities assumed in excess of the basis of the property transferred are gain: $90,000 - $70,000 = $20,000.", 20000),
("In a section 351 transfer, stock a person receives only for services:",
 "Is taxable compensation", ["Counts toward 80% control", "Is tax-free if control is met", "Is a long-term capital gain"],
 "Services are not property for section 351, so stock received for them is ordinary income at its value and the service provider is not a transferor of property."),
("A C corporation with ample earnings and profits distributes land with a basis of $30,000 and a value of $90,000 to its sole shareholder. The corporation recognizes gain of:",
 "$60,000", ["$0", "$90,000", "$30,000"],
 "Under section 311(b) a corporation recognizes gain on distributing appreciated property as if it had sold it: $90,000 - $30,000 = $60,000.", 60000),
("A C corporation distributes equipment worth $20,000 with a basis of $35,000 to a shareholder as a nonliquidating distribution. The corporation recognizes:",
 "Nothing; the loss is denied", ["A $15,000 ordinary loss", "A $15,000 capital loss", "A $20,000 taxable gain"],
 "Section 311(a) bars a loss on a nonliquidating distribution of depreciated property. Selling the property and distributing the cash would let the corporation deduct the loss."),
("A C corporation has accumulated E&P of $10,000 and current E&P of $15,000. It distributes $40,000 of cash to its sole shareholder, whose stock basis is $8,000. The shareholder's capital gain is:",
 "$7,000", ["$15,000", "$0", "$32,000"],
 "$25,000 is a dividend from current and accumulated E&P. The other $15,000 first returns the $8,000 basis, and the $7,000 excess is capital gain (section 301(c)).", 7000),
("A C corporation completely liquidates and distributes land worth $150,000 to its sole shareholder, whose stock basis is $40,000. Ignoring the corporate tax, the shareholder recognizes:",
 "$110,000 of capital gain", ["$100,000 of capital gain", "$150,000 of dividend", "No gain until he sells"],
 "In a complete liquidation the shareholder treats the property as received in exchange for the stock (section 331): $150,000 - $40,000 = $110,000.", 110000),
("A parent corporation that owns 85% of a subsidiary's stock completely liquidates the subsidiary. The parent generally:",
 "Has no gain and a carryover basis", ["Has capital gain and a new basis", "Has gain on appreciated assets only", "Has no gain but a value basis"],
 "Section 332 gives the 80% parent nonrecognition, and section 334(b) gives it the subsidiary's basis in the assets."),
("A C corporation makes a $150,000 interest-free demand loan to its sole shareholder, who is not an employee. For the corporation, the forgone interest is treated as:",
 "Interest income with no deduction", ["A deduction with no income", "Interest income and a deduction", "Nothing, since it is a demand loan"],
 "For a corporation-shareholder loan, section 7872 treats the forgone interest as a dividend paid to the shareholder and interest earned by the corporation; dividends are not deductible."),
("To file a consolidated return, the common parent must directly own stock of at least one other member that has at least:",
 "80% of vote and value", ["50% of vote or value", "80% of vote only", "More than 50% of value"],
 "An affiliated group under section 1504(a) needs stock with at least 80% of the voting power and 80% of the value, owned directly by includible corporations."),
("Parent P sells inventory costing $40,000 to its subsidiary S for $55,000, and S still holds all of it at year end. S also paid P a $20,000 dividend. P's separate taxable income of $300,000 includes the profit and the dividend; S's is $100,000. Consolidated taxable income is:",
 "$365,000", ["$400,000", "$385,000", "$380,000"],
 "The $15,000 intercompany profit is deferred until S sells the goods outside the group, and the intercompany dividend is eliminated: $400,000 - $15,000 - $20,000 = $365,000.", 365000),
("Which corporation cannot be included in a consolidated federal income tax return?",
 "An S corporation", ["An 85%-owned domestic C corporation", "A subsidiary with an NOL", "A newly formed domestic subsidiary"],
 "Section 1504(b) excludes S corporations, foreign corporations and tax-exempt organizations, among others, from being includible corporations."),
("A U.S. corporation earns $40,000 of interest from a U.S. corporation, $25,000 of dividends from a French corporation, $30,000 of royalties for a patent used in Japan, and $50,000 for services its staff perform in Ohio for a Mexican client. Its foreign-source income is:",
 "$55,000", ["$105,000", "$80,000", "$90,000"],
 "Dividends from a foreign corporation and royalties for property used abroad are foreign source. Interest is sourced by the payer's residence and services where performed: $25,000 + $30,000 = $55,000.", 55000),
("Under the permanent establishment article of U.S. tax treaties, which activity alone generally does NOT create a permanent establishment?",
 "Using a warehouse only for storage", ["A branch office making sales", "A factory making its goods", "An agent who signs its contracts"],
 "Treaties exclude facilities used solely to store, display or deliver goods, or for other preparatory or auxiliary activities. A sales office, factory or dependent agent concluding contracts creates one."),
("A foreign corporation is a controlled foreign corporation when its U.S. shareholders, each owning at least 10%, together own:",
 "Over 50% of vote or value", ["At least 10% of the vote", "Over 50% of the vote only", "At least 80% of vote and value"],
 "Section 957(a) tests vote or value. A U.S. shareholder is a U.S. person owning at least 10% of the vote or value (section 951(b)). Subpart F income is then taxed currently."),
("A main difference between a foreign branch and a foreign subsidiary of a U.S. corporation is that the branch's:",
 "Losses flow through currently", ["Income is deferred until paid", "Income is never taxed here", "Losses stay with the foreign entity"],
 "A branch is part of the U.S. corporation, so its income and losses are on the U.S. return as earned. A subsidiary is a separate foreign corporation."),
("A foreign corporation with no U.S. trade or business receives $200,000 of U.S.-source dividends, and no treaty applies. The tax withheld at source is:",
 "$60,000", ["$42,000", "$20,000", "$0"],
 "Fixed or determinable income of a foreign corporation not connected with a U.S. business is subject to 30% withholding (sections 881 and 1442): 30% x $200,000.", 60000),
]
